import{_ as r,o as a,c as t,a3 as s}from"./chunks/framework.DDcl5AtZ.js";const h=JSON.parse('{"title":"Kubernetes Provisioners and Providers","description":"","frontmatter":{},"headers":[],"relativePath":"provisioner/operating-services.md","filePath":"provisioner/operating-services.md"}'),n={name:"provisioner/operating-services.md"};function i(o,e,l,c,d,p){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="kubernetes-provisioners-and-providers" tabindex="-1">Kubernetes Provisioners and Providers <a class="header-anchor" href="#kubernetes-provisioners-and-providers" aria-label="Permalink to &quot;Kubernetes Provisioners and Providers&quot;">​</a></h1><p>Provisioners review namespace changes and maintain the Kubernetes APIs and operators that the factory integrates with. The CI workflow checks commit formatting, Ansible lint and syntax, and the host-variable schema; it does not connect to a cluster or apply changes.</p><h2 id="review-a-namespace-change" tabindex="-1">Review a namespace change <a class="header-anchor" href="#review-a-namespace-change" aria-label="Permalink to &quot;Review a namespace change&quot;">​</a></h2><p>Before approving a pull request:</p><ol><li>Confirm the inventory host and its matching <code>host_vars/&lt;host&gt;.yaml</code> entry are correct.</li><li>Review the namespace name, ownership labels and annotations, and any requested resource quota or container defaults.</li><li>Check external references such as secret-store names, remote secret keys, Gateway names, DNS records, ConfigMap file paths, and backends.</li><li>Confirm the requested resources and API versions are supported by the target cluster and do not exceed its capacity.</li><li>Review the successful CI checks. They do not replace a provider-side review or a test against the intended cluster.</li></ol><h2 id="integrated-kubernetes-resources" tabindex="-1">Integrated Kubernetes resources <a class="header-anchor" href="#integrated-kubernetes-resources" aria-label="Permalink to &quot;Integrated Kubernetes resources&quot;">​</a></h2><p>The playbook currently manages:</p><ul><li>Namespaces and their labels and annotations.</li><li>ResourceQuotas and LimitRanges, when enabled in the host or shared defaults.</li><li>ExternalSecret resources backed by an existing ClusterSecretStore.</li><li>ConfigMaps populated from inline values or files in the repository.</li><li>Gateway API HTTPRoutes that refer to an existing Gateway and Service.</li><li>ExternalDNS DNSEndpoint resources.</li></ul><h2 id="cluster-and-provider-prerequisites" tabindex="-1">Cluster and provider prerequisites <a class="header-anchor" href="#cluster-and-provider-prerequisites" aria-label="Permalink to &quot;Cluster and provider prerequisites&quot;">​</a></h2><p>Install the Kubernetes APIs and controllers required by the resources you configure:</p><ul><li>Gateway API CRDs and a Gateway implementation for HTTPRoutes.</li><li>External Secrets Operator and the referenced ClusterSecretStore for ExternalSecrets.</li><li>ExternalDNS and its DNSEndpoint CRD for DNS records.</li><li>The Kubernetes API types for built-in Namespace, ResourceQuota, LimitRange, and ConfigMap resources.</li></ul><p>The provider or cluster operator is responsible for controller configuration, credentials, access policies, DNS zones, and ensuring referenced objects exist. These dependencies are not created by this repository.</p>',12)])])}const v=r(n,[["render",i]]);export{h as __pageData,v as default};
